// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** One temperature (and humidity) reading of a medicine store, refrigerator, freezer or cold-chain box (MSDS MOM 58). */
export interface StorageCheckIn {
  /** Always the same spelling for the same place: the register groups by it */
  storage_area: string;
  storage_kind: "Room" | "Refrigerator" | "Freezer" | "ColdChainBox";
  /** The ward whose cupboard or refrigerator it is; null for the pharmacy (GET /beds/matrix?include_beds=false) */
  ward_id?: number | null;
  /** Degrees Celsius, one decimal */
  temperature_c: number | string;
  humidity_pct?: number | string | null;
  /** Own limits for this place (a vaccine box): both or neither; default the settings of the storage kind (pharmacy_room_*_c, pharmacy_fridge_*_c, pharmacy_freezer_*_c) */
  min_c?: number | string | null;
  max_c?: number | string | null;
  /** Required when the reading is out of range (STORAGE_CHECK_ACTION_REQUIRED) */
  action_taken?: string | null;
}

/** One reading of the medicine storage log, with the limits that applied. */
export interface StorageCheckOut {
  check_id: number;
  storage_area: string;
  storage_kind: "Room" | "Refrigerator" | "Freezer" | "ColdChainBox";
  ward_id: number | null;
  ward_name: string | null;
  recorded_at: string;
  temperature_c: number;
  humidity_pct: number | null;
  min_c: number;
  max_c: number;
  /** False: show the row red; action_taken says what was done */
  within_range: boolean;
  action_taken: string | null;
  recorded_by: number;
  recorded_by_name: string;
}

/** The storage log of a period, by storage area (the surveyor's view; MSDS MOM 58). */
export interface StorageSummaryOut {
  date_from: string;
  date_to: string;
  days: number;
  checks_per_day: number;
  /** The limits in force today */
  ranges: StorageRangesOut;
  areas: StorageAreaSummaryOut[];
  checks: number;
  out_of_range: number;
}

export interface StorageRangesOut {
  room_min: number;
  room_max: number;
  fridge_min: number;
  fridge_max: number;
  freezer_min: number;
  freezer_max: number;
}

export interface StorageAreaSummaryOut {
  storage_area: string;
  storage_kind: "Room" | "Refrigerator" | "Freezer" | "ColdChainBox";
  ward_name: string | null;
  checks: number;
  out_of_range: number;
  min_seen: number;
  max_seen: number;
  last_at: string;
  /** Days with at least one reading */
  days_checked: number;
  /** Days with the full routine (checks_per_day readings) */
  days_complete: number;
}

export interface BedMatrixOut {
  wards: WardOccupancyOut[];
  /** Ward name -> available beds */
  summary: Record<string, number>;
  /** Only with include_beds=true */
  beds?: BedMatrixBedOut[] | null;
}

/** A ward's bed counts (view v_bed_matrix). */
export interface WardOccupancyOut {
  ward_id: number;
  code: string;
  name: string;
  ward_type: "General" | "Private" | "SemiPrivate" | "ICU" | "CCU" | "NICU" | "Surgical" | "Pediatric" | "Maternity" | "Emergency" | "Isolation" | "Other";
  gender_restriction: "male" | "female" | "any";
  total_beds: number;
  available: number;
  reserved: number;
  occupied: number;
  /** Beds being cleaned or waiting for discharge clearance */
  turnover: number;
  out_of_service: number;
}

export interface BedMatrixBedOut {
  bed_id: number;
  ward_id: number;
  label: string;
  current_state: "Available" | "Reserved" | "Occupied" | "Dirty" | "Cleaning" | "OutOfService";
  state_changed_at: string;
  is_overflow_allowed: boolean;
  admission_id: number | null;
  /** Only with with_patients=true */
  patient_name: string | null;
  /** Only with with_patients=true */
  mrn: string | null;
  admission_status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled" | null;
  is_overflow: boolean | null;
  /** The discharge stage the patient in this bed waits for */
  discharge_blocked_on: string | null;
}

/** Record a temperature (and humidity) reading of a medicine store, refrigerator or freezer — POST /api/v1/pharmacy/storage-checks (who may call: holders of pharmacy.storage.record). */
export function recordStorageCheck(body: StorageCheckIn): Promise<StorageCheckOut> {
  return api<StorageCheckOut>("POST", `/pharmacy/storage-checks`, body, { idempotent: true });
}

/** The storage log — GET /api/v1/pharmacy/storage-checks (who may call: holders of pharmacy.stock.view or medication.safety.view or pharmacy.storage.record). */
export function listStorageChecks(query?: { date_from?: string | null; date_to?: string | null; storage_area?: string | null; ward_id?: number | null; out_of_range_only?: boolean; limit?: number }): Promise<StorageCheckOut[]> {
  return api<StorageCheckOut[]>("GET", withQuery(`/pharmacy/storage-checks`, query), undefined);
}

/** The storage log by storage area: readings, out of range, days with the full routine — GET /api/v1/pharmacy/storage-checks/summary (who may call: holders of pharmacy.stock.view or medication.safety.view or pharmacy.storage.record). */
export function storageSummary(query?: { date_from?: string | null; date_to?: string | null }): Promise<StorageSummaryOut> {
  return api<StorageSummaryOut>("GET", withQuery(`/pharmacy/storage-checks/summary`, query), undefined);
}

/** The storage register of a period as a PDF (MSDS MOM 58) — GET /api/v1/pharmacy/storage-checks/register/pdf (who may call: holders of pharmacy.stock.view or medication.safety.view or pharmacy.storage.record). */
export function storageRegisterPdf(query?: { date_from?: string | null; date_to?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/pharmacy/storage-checks/register/pdf`, query), undefined);
}

/** Live bed matrix (counts per ward + optional bed list) — GET /api/v1/beds/matrix (who may call: holders of ipd.bed.view or cssd.operate or infection.control.manage or complaint.manage or incident.view or facility.drill.manage or roster.manage.all or facility.equipment.manage or pharmacy.storage.record). */
export function bedMatrix(query?: { include_beds?: boolean }): Promise<BedMatrixOut> {
  return api<BedMatrixOut>("GET", withQuery(`/beds/matrix`, query), undefined);
}
